def ensure_audit_log_file():
    path = get_audit_log_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    if not path.exists():
        path.write_text("[]\n", encoding="utf-8")
    return path


def load_strategic_contacts():
    path = ensure_strategic_contacts_file()

    try:
        with STRATEGIC_CONTACTS_LOCK:
            payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return []

    if not isinstance(payload, list):
        return []

    normalized = []
    changed = False
    for item in payload:
        if not isinstance(item, dict):
            changed = True
            continue
        normalized_item = normalize_strategic_contact_record(item)
        if normalized_item["id"]:
            normalized.append(normalized_item)
        else:
            changed = True

    if changed:
        save_strategic_contacts(normalized)

    return normalized


def save_strategic_contacts(items):
    path = ensure_strategic_contacts_file()
    with STRATEGIC_CONTACTS_LOCK:
        path.write_text(json.dumps(items, indent=2), encoding="utf-8")


def load_audit_log_entries():
    path = ensure_audit_log_file()

    try:
        with AUDIT_LOG_LOCK:
            payload = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return []

    if not isinstance(payload, list):
        return []

    entries = []
    for item in payload:
        if not isinstance(item, dict):
            continue
        entries.append(
            {
                "timestamp": str(item.get("timestamp") or "").strip(),
                "username": str(item.get("username") or "").strip(),
                "display_name": str(item.get("display_name") or "").strip(),
                "action": str(item.get("action") or "").strip(),
                "target": str(item.get("target") or "").strip(),
                "details": str(item.get("details") or "").strip(),
                "area": str(item.get("area") or "general").strip() or "general",
                "status": str(item.get("status") or "success").strip() or "success",
            }
        )

    return entries


def record_audit_event(action, target="", details="", user=None, area="general", status="success"):
    current_user = user or get_current_session_user() or {}
    entry = {
        "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "username": str(current_user.get("username") or "").strip(),
        "display_name": str(
            current_user.get("display_name")
            or current_user.get("username")
            or ""
        ).strip(),
        "action": str(action or "").strip(),
        "target": str(target or "").strip(),
        "details": str(details or "").strip(),
        "area": str(area or "general").strip(),
        "status": str(status or "success").strip(),
    }

    path = ensure_audit_log_file()
    try:
        with AUDIT_LOG_LOCK:
            try:
                payload = json.loads(path.read_text(encoding="utf-8"))
            except Exception:
                payload = []

            if not isinstance(payload, list):
                payload = []

            payload.append(entry)
            payload = payload[-5000:]
            path.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    except Exception:
        pass


