@app.get("/admin-audit-log", response_class=HTMLResponse)
def get_admin_audit_log_page(area: str = "", status: str = "", user: str = "", action: str = "", q: str = "", message: str = "", error: str = ""):
    current_user = get_current_session_user()
    if not can_manage_user_accounts(current_user):
        return render_page(
            title="Audit Log",
            body="<p class='status error'>You do not have permission to view the audit log.</p>",
        )

    all_entries = list(reversed(load_audit_log_entries()))
    area_filter = str(area or "").strip().lower()
    status_filter = str(status or "").strip().lower()
    user_filter = str(user or "").strip().lower()
    action_filter = str(action or "").strip().lower()
    query_filter = str(q or "").strip().lower()
    entries = []
    for entry in all_entries:
        if area_filter and str(entry.get("area") or "").lower() != area_filter:
            continue
        if status_filter and str(entry.get("status") or "").lower() != status_filter:
            continue
        if user_filter and str(entry.get("username") or "").lower() != user_filter:
            continue
        if action_filter and action_filter not in str(entry.get("action") or "").lower():
            continue
        haystack = " ".join(str(entry.get(key) or "") for key in ("display_name", "username", "action", "target", "details", "area", "status")).lower()
        if query_filter and query_filter not in haystack:
            continue
        entries.append(entry)
    areas = sorted({str(item.get("area") or "general") for item in all_entries})
    users = sorted({str(item.get("username") or "") for item in all_entries if item.get("username")})
    statuses = sorted({str(item.get("status") or "success") for item in all_entries})
    area_options = "".join(f'<option value="{escape(value)}"{" selected" if value.lower() == area_filter else ""}>{escape(value.replace("-", " ").title())}</option>' for value in areas)
    user_options = "".join(f'<option value="{escape(value)}"{" selected" if value.lower() == user_filter else ""}>{escape(value)}</option>' for value in users)
    status_options = "".join(f'<option value="{escape(value)}"{" selected" if value.lower() == status_filter else ""}>{escape(value.title())}</option>' for value in statuses)
    rows = []
    for entry in entries[:200]:
        display_name = str(entry.get("display_name") or entry.get("username") or "Unknown user").strip()
        details = str(entry.get("details") or "").strip()
        target = str(entry.get("target") or "").strip()
        summary_parts = [part for part in [target, details] if part]
        rows.append(
            "<tr>"
            f"<td>{escape(str(entry.get('timestamp') or ''))}</td>"
            f"<td>{escape(display_name)}</td>"
            f"<td>{escape(str(entry.get('area') or 'general').replace('-', ' ').title())}</td>"
            f"<td>{escape(str(entry.get('action') or ''))}</td>"
            f"<td><span class='audit-status audit-status-{escape(str(entry.get('status') or 'success').lower())}'>{escape(str(entry.get('status') or 'success').title())}</span></td>"
            f"<td>{escape(' • '.join(summary_parts) or '—')}</td>"
            "</tr>"
        )

    rows_markup = "".join(rows) or "<tr><td colspan='6'>No audit activity matches these filters.</td></tr>"
    status_markup = ""
    if message:
        status_markup = f"<p class='status ok'>{escape(message)}</p>"
    elif error:
        status_markup = f"<p class='status error'>{escape(error)}</p>"

    body = f"""
        <section class="panel">
            <h2>Audit log</h2>
            <p class="subtle">Admin-only activity history for sign-ins, customer communication, calendar changes, FileMaker synchronisation and other key actions.</p>
            {status_markup}
            <form class="audit-filter-form" method="get" action="/admin-audit-log">
                <label><span>Area</span><select name="area"><option value="">All areas</option>{area_options}</select></label>
                <label><span>Status</span><select name="status"><option value="">All statuses</option>{status_options}</select></label>
                <label><span>User</span><select name="user"><option value="">All users</option>{user_options}</select></label>
                <label><span>Action</span><input name="action" value="{escape(action)}" placeholder="e.g. send-email"></label>
                <label class="audit-filter-search"><span>Search</span><input name="q" value="{escape(q)}" placeholder="Customer or detail"></label>
                <button class="button small-button" type="submit">Filter</button>
                <a class="button secondary small-button" href="/admin-audit-log">Clear</a>
            </form>
            <div class="summary compact-summary">
                <div>
                    <span class="label">Entries shown</span>
                    <strong>{min(len(entries), 200)}</strong>
                </div>
                <div>
                    <span class="label">Total saved</span>
                    <strong>{len(all_entries)}</strong>
                </div>
            </div>
            <div class="table-wrap">
                <table class="user-accounts-table audit-table">
                    <thead>
                        <tr>
                            <th>When</th>
                            <th>User</th>
                            <th>Area</th>
                            <th>Action</th>
                            <th>Status</th>
                            <th>Summary</th>
                        </tr>
                    </thead>
                    <tbody>{rows_markup}</tbody>
                </table>
            </div>
        </section>
    """
    return render_page(title="Audit Log", body=body)


@app.post("/user-accounts", response_class=HTMLResponse)
def post_user_account(
    display_name: str = Form(""),
    username: str = Form(""),
    m365_email: str = Form(""),
    role: str = Form("user"),
    password: str = Form(""),
    active: str = Form("active"),
):
    current_user = get_current_session_user()
    if not can_manage_user_accounts(current_user):
        return render_page(
            title="User Accounts",
            body="<p class='status error'>You do not have permission to manage user accounts.</p>",
        )

    display_name = str(display_name or "").strip()
    username = normalize_username(username)
    m365_email = str(m365_email or "").strip().lower()
    role = "admin" if str(role or "").strip().lower() == "admin" else "user"
    password = str(password or "")

    if not display_name or not username or not m365_email or not password:
        return RedirectResponse(
            url=f"/user-accounts?error={quote('Please complete every field.')}",
            status_code=303,
        )

    users = load_app_users()
    if any(normalize_username(user.get("username")) == username for user in users):
        return RedirectResponse(
            url=f"/user-accounts?error={quote('That username already exists.')}",
            status_code=303,
        )

    password_payload = hash_user_password(password)
    users.append(
        {
            "username": username,
            "display_name": display_name,
            "m365_email": m365_email,
            "role": role,
            "active": str(active or "").strip().lower() != "inactive",
            "skip_send_confirmation": False,
            "password_salt": password_payload["salt"],
            "password_hash": password_payload["hash"],
        }
    )
    save_app_users(users)
    record_audit_event(
        "user-create",
        target=username,
        details=f"Role: {role} • Mailbox: {m365_email}",
        user=current_user,
        area="administration",
    )
    return RedirectResponse(
        url=f"/user-accounts?message={quote('User created successfully.')}",
        status_code=303,
    )


@app.post("/user-accounts/update", response_class=HTMLResponse)
def post_user_account_update(
    request: Request,
    original_username: str = Form(""),
    display_name: str = Form(""),
    username: str = Form(""),
    m365_email: str = Form(""),
    role: str = Form("user"),
    password: str = Form(""),
    active: str = Form("active"),
):
    current_user = get_current_session_user()
    if not can_manage_user_accounts(current_user):
        return render_page(
            title="User Accounts",
            body="<p class='status error'>You do not have permission to manage user accounts.</p>",
        )

    original_username = normalize_username(original_username)
    display_name = str(display_name or "").strip()
    username = normalize_username(username)
    m365_email = str(m365_email or "").strip().lower()
    role = "admin" if str(role or "").strip().lower() == "admin" else "user"
    password = str(password or "")
    is_active = str(active or "").strip().lower() != "inactive"

    if not original_username:
        return RedirectResponse(
            url=f"/user-accounts?error={quote('Could not identify the user to edit.')}",
            status_code=303,
        )

    if not display_name or not username or not m365_email:
        return RedirectResponse(
            url=f"/user-accounts?edit={quote(original_username)}&error={quote('Please complete every required field.')}",
            status_code=303,
        )

    users = load_app_users()
    match_index = next(
        (index for index, user in enumerate(users) if normalize_username(user.get('username')) == original_username),
        None,
    )
    if match_index is None:
        return RedirectResponse(
            url=f"/user-accounts?error={quote('That user no longer exists.')}",
            status_code=303,
        )

    if any(
        normalize_username(user.get("username")) == username
        for index, user in enumerate(users)
        if index != match_index
    ):
        return RedirectResponse(
            url=f"/user-accounts?edit={quote(original_username)}&error={quote('That username already exists.')}",
            status_code=303,
        )

    user_record = dict(users[match_index])
    old_username = normalize_username(user_record.get("username"))
    old_m365_email = str(user_record.get("m365_email") or "").strip().lower()
    user_record["display_name"] = display_name
    user_record["username"] = username
    user_record["m365_email"] = m365_email
    user_record["role"] = role
    user_record["active"] = is_active
    user_record["skip_send_confirmation"] = bool(user_record.get("skip_send_confirmation", False))

    if password.strip():
        password_payload = hash_user_password(password)
        user_record["password_salt"] = password_payload["salt"]
        user_record["password_hash"] = password_payload["hash"]

    users[match_index] = user_record
    save_app_users(users)

    existing_token = get_m365_token_record(old_username)
    if old_username != username and existing_token:
        set_m365_token_record(username, existing_token)
        delete_m365_token_record(old_username)

    token_record = get_m365_token_record(username)
    token_cleared = False
    if token_record:
        connected_email = str(token_record.get("connected_email") or "").strip().lower()
        if old_m365_email != m365_email and connected_email and connected_email != m365_email:
            delete_m365_token_record(username)
            token_cleared = True

    if current_user and normalize_username(current_user.get("username")) == old_username:
        request.session["app_username"] = username

    message = "User updated successfully."
    if token_cleared:
        message += " Microsoft 365 connection was cleared because the mailbox changed."

    record_audit_event(
        "user-update",
        target=username,
        details=f"Role: {role} • {'Active' if is_active else 'Inactive'}{' • password changed' if password.strip() else ''}",
        user=current_user,
        area="administration",
    )

    return RedirectResponse(
        url=f"/user-accounts?message={quote(message)}",
        status_code=303,
    )


