def format_production_number(value, suffix="", currency=False, decimals=0):
    if value is None:
        return "—"
    value = float(value)
    return f"${value:,.{decimals}f}" if currency else f"{value:,.{decimals}f}{suffix}"


def render_production_period_control(days):
    options = [(30, "1 month"), (60, "2 months"), (90, "3 months"), (120, "4 months"), (150, "5 months"), (180, "6 months")]
    return "".join(
        f'<a class="production-period-chip{" active" if days == value else ""}" href="/production-analysis-view?days={value}">{escape(label)}</a>'
        for value, label in options
    )


def render_production_trend_chart(rows):
    if not rows:
        return '<p class="empty-action">No production history is available for this period.</p>'
    series = [("sort_throughput", "Sort", "#245cff"), ("grind_throughput", "Grind", "#00a884"), ("press_throughput", "Press", "#f59e0b"), ("trim_throughput", "Trim", "#8b5cf6")]
    weekly_rows = build_weekly_throughput_rows(rows, [key for key, _, _ in series])
    if not weekly_rows:
        return '<p class="empty-action">No dated production history is available for this period.</p>'
    maximum = max([float(item[key]) for item in weekly_rows for key, _, _ in series if item.get(key) is not None] or [1]) or 1
    width, height, left, top, bottom = 760, 230, 48, 18, 34
    plot_width, plot_height = width - left - 18, height - top - bottom
    point_count = max(len(weekly_rows) - 1, 1)
    lines = []
    for key, label, color in series:
        points = []
        circles = []
        for index, item in enumerate(weekly_rows):
            if item.get(key) is None:
                continue
            x = left + (index / point_count) * plot_width
            y = top + plot_height - ((float(item[key]) / maximum) * plot_height)
            points.append(f"{x:.1f},{y:.1f}")
            circles.append(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="2.4" fill="{color}"><title>{escape(label)} · week of {escape(item["week_label"])}: {float(item[key]):,.0f} LF average</title></circle>')
        if points:
            lines.append(f'<g class="production-chart-series" data-production-series="{key}"><polyline points="{" ".join(points)}" fill="none" stroke="{color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>{"".join(circles)}</g>')
    legend = '<button type="button" class="production-chart-legend-button active" data-production-series="all" aria-pressed="true" title="Show all departments">All</button>' + "".join(f'<button type="button" class="production-chart-legend-button" data-production-series="{key}" aria-pressed="false" title="Show {escape(label)} only"><i style="background:{color}"></i>{escape(label)}</button>' for key, label, color in series)
    midpoint = maximum / 2
    return f"""
        <div class="production-trend-component">
        <div class="production-chart-legend" aria-label="Choose a department to isolate">{legend}</div>
        <p class="production-chart-note">Select a department to isolate it or All to reset · weekly average per recorded production day · blanks excluded</p>
        <svg class="production-trend-chart" viewBox="0 0 {width} {height}" role="img" aria-label="Weekly average department throughput trend">
            <line x1="{left}" y1="{top}" x2="{width - 18}" y2="{top}" stroke="#edf2f7"/>
            <line x1="{left}" y1="{top + (plot_height / 2)}" x2="{width - 18}" y2="{top + (plot_height / 2)}" stroke="#edf2f7" stroke-dasharray="3 4"/>
            <line x1="{left}" y1="{top + plot_height}" x2="{width - 18}" y2="{top + plot_height}" stroke="#dce7f2"/><line x1="{left}" y1="{top}" x2="{left}" y2="{top + plot_height}" stroke="#dce7f2"/>
            <text x="{left}" y="{height - 8}" class="production-chart-axis">Week of {escape(weekly_rows[0]['week_label'])}</text><text x="{width - 18}" y="{height - 8}" text-anchor="end" class="production-chart-axis">Week of {escape(weekly_rows[-1]['week_label'])}</text>
            <text x="{left - 8}" y="{top + 5}" text-anchor="end" class="production-chart-axis">{maximum:,.0f}</text><text x="{left - 8}" y="{top + (plot_height / 2) + 4}" text-anchor="end" class="production-chart-axis">{midpoint:,.0f}</text><text x="{left - 8}" y="{top + plot_height}" text-anchor="end" class="production-chart-axis">0</text>{''.join(lines)}
        </svg>
        </div>
        <script>
            (() => {{
                const component = document.currentScript.previousElementSibling;
                const buttons = Array.from(component.querySelectorAll('.production-chart-legend-button'));
                const chartSeries = Array.from(component.querySelectorAll('.production-chart-series'));
                buttons.forEach((button) => button.addEventListener('click', () => {{
                    const selected = button.dataset.productionSeries;
                    const isAlreadySelected = button.getAttribute('aria-pressed') === 'true';
                    const showAll = selected === 'all' || isAlreadySelected;
                    buttons.forEach((item) => {{
                        const isActive = showAll ? item.dataset.productionSeries === 'all' : item.dataset.productionSeries === selected;
                        item.setAttribute('aria-pressed', isActive ? 'true' : 'false');
                        item.classList.toggle('active', isActive);
                        item.classList.toggle('muted', !showAll && item.dataset.productionSeries !== 'all' && !isActive);
                    }});
                    chartSeries.forEach((item) => {{
                        item.style.display = (!showAll && item.dataset.productionSeries !== selected) ? 'none' : '';
                    }});
                }}));
            }})();
        </script>
    """


def build_weekly_throughput_rows(rows, keys):
    weeks = {}
    for item in rows:
        try:
            activity_date = datetime.strptime(str(item.get("date") or "")[:10], "%Y-%m-%d")
        except (TypeError, ValueError):
            continue
        week_start = activity_date - timedelta(days=activity_date.weekday())
        bucket = weeks.setdefault(week_start, {key: [] for key in keys})
        for key in keys:
            if item.get(key) is not None:
                bucket[key].append(float(item[key]))
    return [
        {
            "week_start": week_start.strftime("%Y-%m-%d"),
            "week_label": week_start.strftime("%d %b"),
            **{key: (sum(values[key]) / len(values[key]) if values[key] else None) for key in keys},
        }
        for week_start, values in sorted(weeks.items())
    ]


def render_production_flow(latest, rows):
    department_config = [("Sort", "sort_throughput", "backlog_sort", "#245cff"), ("Grind", "grind_throughput", "backlog_grind", "#00a884"), ("Press", "press_throughput", "backlog_press", "#f59e0b"), ("Trim", "trim_throughput", "backlog_trim", "#8b5cf6")]
    departments = []
    for label, throughput_key, backlog_key, color in department_config:
        activity = next((item for item in reversed(rows) if item.get(throughput_key) is not None), {})
        departments.append((label, activity.get(throughput_key), latest.get(backlog_key), activity.get("date"), color))
    maximum = max([float(value or 0) for _, value, _, _, _ in departments] or [1]) or 1
    return "".join(f"""
        <div class="production-flow-row"><strong>{label}</strong><div class="production-flow-track"><span style="width:{((float(throughput or 0) / maximum) * 100) if throughput else 0:.1f}%;background:{color}"></span></div><div class="production-flow-values"><b>{format_production_number(throughput)} LF <small>· {escape(format_optional_datetime(activity_date))}</small></b><span>{format_production_number(backlog)} current backlog</span></div></div>
    """ for label, throughput, backlog, activity_date, color in departments)


def render_press_cards(rows):
    cards = []
    for press in (1, 2, 3):
        activity = next(
            (
                item for item in reversed(rows)
                if any(item.get(f"ff{press}_{field}") is not None for field in ("lf", "mats", "cycles"))
            ),
            {},
        )
        activity_date = format_optional_datetime(activity.get("date")) if activity else "No recorded activity"
        cards.append(f"""
            <article class="production-press-card">
                <div class="production-press-head"><div><strong>FF{press}</strong><small>{escape(activity_date)}</small></div><span>{format_production_number(activity.get(f'ff{press}_utilisation'), '%', decimals=1)}</span></div>
                <div class="production-press-metrics"><span><b>{format_production_number(activity.get(f'ff{press}_mats'))}</b>Mats</span><span><b>{format_production_number(activity.get(f'ff{press}_lf'))}</b>Linear ft</span><span><b>{format_production_number(activity.get(f'ff{press}_cycles'))}</b>Cycles</span></div>
                <small>{format_production_number(activity.get(f'ff{press}_lost_hours'), ' hrs', decimals=1)} lost time</small>
            </article>
        """)
    return "".join(cards)


def render_recook_trend(rows):
    recent = rows[-30:]
    if not recent:
        return '<p class="empty-action">No re-cook history is available.</p>'
    maximum = max([float(item.get("recook_lf") or 0) for item in recent] or [1]) or 1
    bars = "".join(f'<span class="production-recook-bar" style="height:{((float(item.get("recook_lf") or 0) / maximum) * 100) if item.get("recook_lf") else 2:.1f}%" title="{escape(format_optional_datetime(item.get("date")))}: {float(item.get("recook_lf") or 0):,.0f} LF"></span>' for item in recent)
    return f'<div class="production-recook-chart">{bars}</div><div class="production-recook-axis"><span>{escape(format_optional_datetime(recent[0].get("date")))}</span><span>{escape(format_optional_datetime(recent[-1].get("date")))}</span></div>'


def render_operator_analysis(rows):
    if not rows:
        return '<p class="empty-action">No operator history is available for this period.</p>'
    body = "".join(f'''<tr>
        <td data-sort-value="{escape(str(item.get('name') or '').casefold())}"><strong>{escape(item.get('name') or '')}</strong></td>
        <td data-sort-value="{int(item.get('days') or 0)}">{int(item.get('days') or 0)}</td>
        <td data-sort-value="{'' if item.get('productivity') is None else float(item['productivity'])}">{format_production_number(item.get('productivity'), '%', decimals=1)}</td>
        <td data-sort-value="{'' if item.get('target_achieved') is None else float(item['target_achieved'])}">{format_production_number(item.get('target_achieved'), '%', decimals=1)}</td>
        <td data-sort-value="{'' if item.get('booked_hours') is None else float(item['booked_hours'])}">{format_production_number(item.get('booked_hours'), ' hrs', decimals=1)}</td>
    </tr>''' for item in rows)
    headings = [("Operator", "text", "ascending"), ("Active days", "number", "descending"), ("Productivity", "number", "descending"), ("LF target", "number", "descending"), ("Booked", "number", "descending")]
    header = "".join(f'<th aria-sort="none"><button type="button" class="production-table-sort" data-column="{index}" data-type="{data_type}" data-default-direction="{direction}">{escape(label)}</button></th>' for index, (label, data_type, direction) in enumerate(headings))
    return f'''
        <div class="table-wrap production-operator-table-wrap">
            <table class="production-operator-table"><thead><tr>{header}</tr></thead><tbody>{body}</tbody></table>
        </div>
        <script>
            (() => {{
                const wrapper = document.currentScript.previousElementSibling;
                const table = wrapper.querySelector('.production-operator-table');
                const tbody = table.querySelector('tbody');
                const headers = Array.from(table.querySelectorAll('th'));
                table.querySelectorAll('.production-table-sort').forEach((button) => button.addEventListener('click', () => {{
                    const headerCell = button.closest('th');
                    const currentDirection = headerCell.getAttribute('aria-sort');
                    const direction = currentDirection === 'ascending' ? 'descending' : currentDirection === 'descending' ? 'ascending' : button.dataset.defaultDirection;
                    const column = Number(button.dataset.column);
                    const dataType = button.dataset.type;
                    const rows = Array.from(tbody.querySelectorAll('tr'));
                    rows.sort((first, second) => {{
                        const firstValue = first.cells[column].dataset.sortValue || '';
                        const secondValue = second.cells[column].dataset.sortValue || '';
                        if (firstValue === '' && secondValue !== '') return 1;
                        if (secondValue === '' && firstValue !== '') return -1;
                        const comparison = dataType === 'number'
                            ? Number(firstValue) - Number(secondValue)
                            : firstValue.localeCompare(secondValue, undefined, {{ sensitivity: 'base' }});
                        return direction === 'ascending' ? comparison : -comparison;
                    }});
                    headers.forEach((item) => item.setAttribute('aria-sort', 'none'));
                    headerCell.setAttribute('aria-sort', direction);
                    rows.forEach((row) => tbody.appendChild(row));
                }}));
            }})();
        </script>
    '''


def parse_calendar_month(value):
    try:
        return datetime.strptime(str(value or ""), "%Y-%m").replace(day=1)
    except ValueError:
        return datetime.now(UK_TIMEZONE).replace(day=1, hour=0, minute=0, second=0, microsecond=0)


def calendar_event_datetime(event, key="start"):
    try:
        return datetime.fromisoformat(str(event.get(key) or ""))
    except (TypeError, ValueError):
        return None


def format_calendar_event_time(event):
    if event.get("is_all_day"):
        return "All day"
    start = calendar_event_datetime(event, "start")
    end = calendar_event_datetime(event, "end")
    if not start:
        return "Time not available"
    if end:
        return f"{start.strftime('%H:%M')}–{end.strftime('%H:%M')}"
    return start.strftime("%H:%M")


def calendar_event_form_value(event, key, fallback):
    parsed = calendar_event_datetime(event, key)
    return parsed.strftime("%Y-%m-%dT%H:%M") if parsed else fallback


def calendar_event_covers_date(event, selected_date):
    start = calendar_event_datetime(event, "start")
    end = calendar_event_datetime(event, "end")
    if not start:
        return False
    first_day = start.date()
    last_day = (end or start).date()
    if end and end > start and end.hour == 0 and end.minute == 0 and end.second == 0:
        last_day -= timedelta(days=1)
    return first_day <= selected_date <= max(first_day, last_day)


def render_calendar_month_grid(events, month_start):
    first_weekday, days_in_month = calendar_module.monthrange(month_start.year, month_start.month)
    grid_start = month_start - timedelta(days=first_weekday)
    grouped = defaultdict(list)
    for event in events:
        start = calendar_event_datetime(event, "start")
        end = calendar_event_datetime(event, "end")
        if start:
            day = start.date()
            final_day = (end or start).date()
            if end and end > start and end.hour == 0 and end.minute == 0 and end.second == 0:
                final_day -= timedelta(days=1)
            while day <= max(start.date(), final_day):
                grouped[day.isoformat()].append(event)
                day += timedelta(days=1)
    headers = "".join(f"<div class='calendar-weekday'>{label}</div>" for label in ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"))
    cells = []
    for offset in range(42):
        day = grid_start + timedelta(days=offset)
        day_key = day.strftime("%Y-%m-%d")
        classes = ["calendar-day"]
        if day.month != month_start.month:
            classes.append("outside")
        if day.date() == datetime.now(UK_TIMEZONE).date():
            classes.append("today")
        day_events = sorted(grouped.get(day_key, []), key=lambda item: str(item.get("start") or ""))
        visible = day_events[:4]
        def event_chip(item):
            return (
            f'''<a class="calendar-event-chip{' all-day' if item.get('is_all_day') else ''}" href="/calendar-view?month={month_start.strftime('%Y-%m')}&edit={quote(str(item.get('id') or ''))}" title="{escape(str(item.get('subject') or ''))}">
                <span>{escape(format_calendar_event_time(item))}</span><strong>{escape(str(item.get('subject') or 'Untitled event'))}</strong>
            </a>'''
            )
        event_markup = "".join(event_chip(item) for item in visible)
        hidden_events = day_events[len(visible):]
        more = (
            f'''<details class="calendar-day-more"><summary>+{len(hidden_events)} more</summary><div>{''.join(event_chip(item) for item in hidden_events)}</div></details>'''
            if hidden_events else ""
        )
        cells.append(f'''<div class="{' '.join(classes)}"><a class="calendar-day-number" href="/calendar-view?view=day&date={day_key}&month={day.strftime('%Y-%m')}" aria-label="View {day.strftime('%A %d %B')}">{day.day}</a><div class="calendar-day-events">{event_markup}{more}</div></div>''')
    return f'<div class="calendar-month-grid">{headers}{"".join(cells)}</div>'


def render_calendar_agenda(events, month_start):
    if not events:
        return "<p class='empty-action'>No events are recorded for this month.</p>"
    grouped = defaultdict(list)
    for event in events:
        grouped[str(event.get("start_date") or "")].append(event)
    sections = []
    for day_key in sorted(grouped):
        try:
            label = datetime.strptime(day_key, "%Y-%m-%d").strftime("%A %d %B")
        except ValueError:
            label = day_key
        items = []
        for event in sorted(grouped[day_key], key=lambda item: str(item.get("start") or "")):
            location = str(event.get("location") or "").strip()
            items.append(f'''<a class="calendar-agenda-event" href="/calendar-view?month={month_start.strftime('%Y-%m')}&edit={quote(str(event.get('id') or ''))}">
                <span>{escape(format_calendar_event_time(event))}</span>
                <strong>{escape(str(event.get('subject') or 'Untitled event'))}</strong>
                <small>{escape(location or 'No location')}</small>
            </a>''')
        sections.append(f"<section class='calendar-agenda-day'><h3>{escape(label)}</h3>{''.join(items)}</section>")
    return "<div class='calendar-agenda'>" + "".join(sections) + "</div>"


def render_calendar_day(events, selected_date, month_start):
    day_events = [item for item in events if calendar_event_covers_date(item, selected_date)]
    day_events.sort(key=lambda item: str(item.get("start") or ""))
    if not day_events:
        return f'''<div class="calendar-day-detail-empty"><strong>No events on {selected_date.strftime('%A %d %B')}</strong><a class="button" href="#calendar-event-editor">Add an event</a></div>'''
    cards = []
    for event in day_events:
        location = str(event.get("location") or "").strip()
        notes = str(event.get("notes") or event.get("body_preview") or "").strip()
        attendees = event.get("attendees") or []
        meta = []
        if location:
            meta.append(location)
        if attendees:
            meta.append(f"{len(attendees)} attendee{'s' if len(attendees) != 1 else ''}")
        multi_day = calendar_event_datetime(event, "start") and calendar_event_datetime(event, "end") and calendar_event_datetime(event, "start").date() != calendar_event_datetime(event, "end").date()
        if multi_day:
            meta.append("Multi-day event")
        cards.append(f'''<a class="calendar-day-detail-card" href="/calendar-view?month={month_start.strftime('%Y-%m')}&view=day&date={selected_date.isoformat()}&edit={quote(str(event.get('id') or ''))}">
            <span class="calendar-day-detail-time">{escape(format_calendar_event_time(event))}</span>
            <div><strong>{escape(str(event.get('subject') or 'Untitled event'))}</strong>{f'<p>{escape(notes)}</p>' if notes else ''}<small>{escape(' · '.join(meta) or 'No additional details')}</small></div>
        </a>''')
    return f'''<div class="calendar-day-detail"><div class="calendar-day-detail-heading"><span>{selected_date.strftime('%A')}</span><strong>{selected_date.strftime('%d')}</strong><small>{selected_date.strftime('%B %Y')}</small></div><div class="calendar-day-detail-list">{''.join(cards)}</div></div>'''


def render_calendar_event_form(event, month_start, selected_date=None):
    event = event or {}
    editing = bool(event.get("id"))
    default_start = datetime.now(UK_TIMEZONE).replace(minute=0, second=0, microsecond=0) + timedelta(hours=1)
    if selected_date:
        default_start = datetime.combine(selected_date, datetime.min.time(), tzinfo=UK_TIMEZONE).replace(hour=9)
    elif default_start.month != month_start.month or default_start.year != month_start.year:
        default_start = month_start.replace(day=1, hour=9)
    default_end = default_start + timedelta(hours=1)
    start_value = calendar_event_form_value(event, "start", default_start.strftime("%Y-%m-%dT%H:%M"))
    end_value = calendar_event_form_value(event, "end", default_end.strftime("%Y-%m-%dT%H:%M"))
    attendees = ", ".join(event.get("attendees") or [])
    action = "/calendar/events/update" if editing else "/calendar/events/create"
    heading = "Edit event" if editing else "Add event"
    recurring_note = "<p class='small muted'>This is an occurrence in a recurring series. Changes apply to this occurrence.</p>" if event.get("series_master_id") else ""
    delete_form = ""
    if editing:
        delete_form = f'''<form class="calendar-delete-form" method="post" action="/calendar/events/delete" onsubmit="return confirm('Delete this event? Attendees may receive a cancellation.');">
            <input type="hidden" name="event_id" value="{escape(str(event.get('id') or ''))}">
            <input type="hidden" name="month" value="{month_start.strftime('%Y-%m')}">
            <button class="button danger" type="submit">Delete event</button>
        </form>'''
    return f'''
        <aside class="panel calendar-editor-panel" id="calendar-event-editor">
            <div class="calendar-editor-head"><h2>{heading}</h2>{f'<a href="/calendar-view?month={month_start.strftime("%Y-%m")}">Close</a>' if editing else ''}</div>
            {recurring_note}
            <form class="calendar-event-form" method="post" action="{action}">
                <input type="hidden" name="event_id" value="{escape(str(event.get('id') or ''))}">
                <input type="hidden" name="month" value="{month_start.strftime('%Y-%m')}">
                <label><span>Event title</span><input name="subject" required value="{escape(str(event.get('subject') or ''))}"></label>
                <div class="calendar-form-row">
                    <label><span>Starts</span><input type="datetime-local" name="start_value" required value="{escape(start_value)}"></label>
                    <label><span>Ends</span><input type="datetime-local" name="end_value" required value="{escape(end_value)}"></label>
                </div>
                <label class="calendar-checkbox"><input type="checkbox" name="is_all_day" value="true"{' checked' if event.get('is_all_day') else ''}><span>All-day event</span></label>
                <label><span>Location</span><input name="location" value="{escape(str(event.get('location') or ''))}" placeholder="Customer or meeting location"></label>
                <label><span>Attendees</span><input name="attendees" value="{escape(attendees)}" placeholder="name@example.com, another@example.com"><small>Adding or changing attendees can send Outlook invitations or updates.</small></label>
                <label><span>Notes</span><textarea name="notes" rows="5">{escape(str(event.get('notes') or event.get('body_preview') or ''))}</textarea></label>
                <div class="calendar-form-actions"><button type="submit">{'Save changes' if editing else 'Add to calendar'}</button>{f'<a class="button secondary" target="_blank" rel="noopener" href="{escape(str(event.get("web_link") or ""))}">Open in Outlook</a>' if event.get('web_link') else ''}</div>
            </form>
            {delete_form}
        </aside>
    '''


@app.get("/api/calendar-events")
def get_calendar_events_api(start: str = "", end: str = "", refresh: bool = False):
    now = datetime.now(UK_TIMEZONE)
    try:
        start_dt = datetime.fromisoformat(start) if start else now.replace(hour=0, minute=0, second=0, microsecond=0)
        end_dt = datetime.fromisoformat(end) if end else start_dt + timedelta(days=14)
    except ValueError:
        return JSONResponse({"status": "invalid_date_range"}, status_code=400)
    return fetch_calendar_events(start_dt, end_dt, force_refresh=refresh)


@app.get("/calendar-view", response_class=HTMLResponse)
def get_calendar_view(month: str = "", view: str = "month", date: str = "", edit: str = "", refresh: bool = False, message: str = "", error: str = ""):
    month_start = parse_calendar_month(month)
    try:
        selected_date = datetime.strptime(date, "%Y-%m-%d").date() if date else datetime.now(UK_TIMEZONE).date()
    except ValueError:
        selected_date = datetime.now(UK_TIMEZONE).date()
    if view == "day" and (selected_date.year != month_start.year or selected_date.month != month_start.month):
        month_start = datetime.combine(selected_date.replace(day=1), datetime.min.time(), tzinfo=UK_TIMEZONE)
    next_month = (month_start.replace(day=28) + timedelta(days=4)).replace(day=1)
    grid_start = month_start - timedelta(days=month_start.weekday())
    grid_end = next_month + timedelta(days=(6 - (next_month - timedelta(days=1)).weekday()))
    result = fetch_calendar_events(grid_start, grid_end, force_refresh=refresh)
    events = result.get("events", []) if result.get("status") == "ok" else []
    editing_event = next((item for item in events if str(item.get("id") or "") == str(edit or "")), {})
    previous_month = (month_start - timedelta(days=1)).strftime("%Y-%m")
    following_month = next_month.strftime("%Y-%m")
    selected_view = view if view in {"month", "agenda", "day"} else "month"
    status_markup = f"<p class='status'>{escape(message)}</p>" if message else ""
    if error or result.get("status") != "ok":
        status_markup += f"<p class='status error'>{escape(error or result.get('error_message') or result.get('status') or 'Calendar unavailable')}</p>"
    if selected_view == "agenda":
        content = render_calendar_agenda(events, month_start)
    elif selected_view == "day":
        content = render_calendar_day(events, selected_date, month_start)
    else:
        content = render_calendar_month_grid(events, month_start)
    if selected_view == "day":
        previous_href = f"/calendar-view?view=day&date={(selected_date - timedelta(days=1)).isoformat()}"
        next_href = f"/calendar-view?view=day&date={(selected_date + timedelta(days=1)).isoformat()}"
        today_href = f"/calendar-view?view=day&date={datetime.now(UK_TIMEZONE).date().isoformat()}"
        title_label = selected_date.strftime("%A %d %B %Y")
    else:
        previous_href = f"/calendar-view?month={previous_month}&view={selected_view}"
        next_href = f"/calendar-view?month={following_month}&view={selected_view}"
        today_href = "/calendar-view"
        title_label = month_start.strftime("%B %Y")
    body = f'''
        {status_markup}
        <div class="calendar-page-layout">
            <section class="panel calendar-main-panel">
                <div class="calendar-toolbar">
                    <div><span class="home-focus-inline-kicker">Shared NuMat Calendar</span><h2>{escape(title_label)}</h2><p class="small muted">Synced {escape(format_optional_datetime(result.get('synced_at')) if result.get('synced_at') else 'not available')}</p></div>
                    <div class="calendar-toolbar-actions">
                        <a class="button secondary" href="{previous_href}">Previous</a>
                        <a class="button secondary" href="{today_href}">Today</a>
                        <a class="button secondary" href="{next_href}">Next</a>
                        <a class="button secondary" href="/calendar-view?month={month_start.strftime('%Y-%m')}&view=month">Month</a>
                        <a class="button secondary" href="/calendar-view?month={month_start.strftime('%Y-%m')}&view=agenda">Agenda</a>
                        <a class="button secondary" href="/calendar-view?month={month_start.strftime('%Y-%m')}&view={selected_view}{f'&date={selected_date.isoformat()}' if selected_view == 'day' else ''}&refresh=true">Refresh</a>
                        <a class="button calendar-add-jump" href="#calendar-event-editor">Add event</a>
                    </div>
                </div>
                {content}
            </section>
            {render_calendar_event_form(editing_event, month_start, selected_date if selected_view == 'day' else None)}
        </div>
    '''
    return render_page(title="Calendar", body=body, main_class="calendar-main")


def calendar_write_redirect(month, result, success_message):
    month_value = parse_calendar_month(month).strftime("%Y-%m")
    if result.get("status") == "ok":
        return RedirectResponse(url=f"/calendar-view?month={month_value}&message={quote(success_message)}", status_code=303)
    return RedirectResponse(url=f"/calendar-view?month={month_value}&error={quote(str(result.get('error_message') or result.get('status') or 'Calendar update failed.'))}", status_code=303)


@app.post("/calendar/events/create")
def post_calendar_event_create(subject: str = Form(""), start_value: str = Form(""), end_value: str = Form(""), is_all_day: str = Form(""), location: str = Form(""), attendees: str = Form(""), notes: str = Form(""), month: str = Form("")):
    result = create_calendar_event(subject=subject, start_value=start_value, end_value=end_value, is_all_day=bool(is_all_day), location=location, attendees=attendees, notes=notes)
    if result.get("status") == "ok":
        record_audit_event("calendar-create", target=subject, details=f"Shared NuMat Calendar • {start_value}", area="calendar")
    return calendar_write_redirect(month, result, "Event added to Shared NuMat Calendar.")


@app.post("/calendar/events/update")
def post_calendar_event_update(event_id: str = Form(""), subject: str = Form(""), start_value: str = Form(""), end_value: str = Form(""), is_all_day: str = Form(""), location: str = Form(""), attendees: str = Form(""), notes: str = Form(""), month: str = Form("")):
    result = update_calendar_event(event_id, subject=subject, start_value=start_value, end_value=end_value, is_all_day=bool(is_all_day), location=location, attendees=attendees, notes=notes)
    if result.get("status") == "ok":
        record_audit_event("calendar-update", target=subject, details=f"Shared NuMat Calendar • {start_value}", area="calendar")
    return calendar_write_redirect(month, result, "Calendar event updated.")


@app.post("/calendar/events/delete")
def post_calendar_event_delete(event_id: str = Form(""), month: str = Form("")):
    result = delete_calendar_event(event_id)
    if result.get("status") == "ok":
        record_audit_event("calendar-delete", target=event_id, details="Shared NuMat Calendar", area="calendar")
    return calendar_write_redirect(month, result, "Calendar event deleted.")


def build_current_month_production_payload(production_result=None, today=None):
    production_result = production_result or fetch_production_analysis_data()
    today = today or datetime.now()
    month_start = today.replace(day=1).strftime("%Y-%m-%d")
    today_key = today.strftime("%Y-%m-%d")
    month_result = {
        **production_result,
        "production_rows": [item for item in production_result.get("production_rows", []) if month_start <= str(item.get("date") or "") < today_key],
        "plant_operator_rows": [item for item in production_result.get("plant_operator_rows", production_result.get("operator_rows", [])) if month_start <= str(item.get("date") or "") < today_key],
        "operator_rows": [item for item in production_result.get("operator_rows", []) if month_start <= str(item.get("date") or "") < today_key],
    }
    payload = build_production_kpi_payload(month_result, days=0)
    month_rows = payload.get("rows", [])
    labour_costs = [float(item["labour_cost"]) for item in month_rows if item.get("labour_cost") is not None]
    invoiced_revenue = next((float(item["invoiced_revenue_mtd"]) for item in reversed(month_rows) if item.get("invoiced_revenue_mtd") is not None), None)
    payload["summary"].update({
        "total_labour_cost": sum(labour_costs) if labour_costs else None,
        "invoiced_revenue_mtd": invoiced_revenue,
        "labour_percentage_mtd": ((sum(labour_costs) / invoiced_revenue) * 100 if labour_costs and invoiced_revenue and invoiced_revenue > 0 else 0.0),
    })
    payload["period_start"] = month_start
    payload["period_end"] = (today - timedelta(days=1)).strftime("%Y-%m-%d")
    return payload


def build_kpi_comparison(current, average, period_label, higher_is_better=True, comparison_available=True, unit="%"):
    return {
        "current": current,
        "average": average,
        "period_label": period_label,
        "higher_is_better": higher_is_better,
        "comparison_available": bool(comparison_available and current is not None and average is not None),
        "unit": unit,
    }


def build_kpi_historical_comparisons(production_result, production_mtd, accounts, today=None):
    today = today or datetime.now()
    today_key = today.strftime("%Y-%m-%d")
    current_month = today.strftime("%Y-%m")

    operators_by_month = defaultdict(list)
    for item in production_result.get("plant_operator_rows", production_result.get("operator_rows", [])):
        month = str(item.get("date") or "")[:7]
        if month and month < current_month and (item.get("clocked_hours") or 0) > 0:
            operators_by_month[month].append(item)
    plant_months = sorted(operators_by_month)[-6:]
    plant_rows = [item for month in plant_months for item in operators_by_month[month]]
    plant_booked = sum(float(item.get("booked_hours") or 0) for item in plant_rows)
    plant_clocked = sum(float(item.get("clocked_hours") or 0) for item in plant_rows)
    plant_average = (plant_booked / plant_clocked * 100) if plant_clocked else None

    production_by_month = defaultdict(list)
    for item in production_result.get("production_rows", []):
        month = str(item.get("date") or "")[:7]
        if month and month < current_month:
            production_by_month[month].append(item)
    labour_months = []
    labour_cost_total = 0.0
    invoiced_total = 0.0
    for month in sorted(production_by_month, reverse=True):
        rows = production_by_month[month]
        costs = [float(item["labour_cost"]) for item in rows if item.get("labour_cost") is not None]
        invoiced = next((float(item["invoiced_revenue_mtd"]) for item in reversed(rows) if item.get("invoiced_revenue_mtd") is not None), None)
        if not costs or not invoiced or invoiced <= 0:
            continue
        labour_months.append(month)
        labour_cost_total += sum(costs)
        invoiced_total += invoiced
        if len(labour_months) == 6:
            break
    labour_average = (labour_cost_total / invoiced_total * 100) if invoiced_total else None

    debtor_valid_from = os.getenv("KPI_DEBTOR_HISTORY_VALID_FROM", "2026-08-03").strip()
    debtor_values = [
        float(item["aged_debtor_days"])
        for item in production_result.get("production_rows", [])
        if item.get("aged_debtor_days") is not None
        and debtor_valid_from <= str(item.get("date") or "") < today_key
    ]
    debtor_average = sum(debtor_values) / len(debtor_values) if debtor_values else None
    current_invoice = float(production_mtd.get("summary", {}).get("invoiced_revenue_mtd") or 0)

    return {
        "plant_productivity": build_kpi_comparison(
            production_mtd.get("summary", {}).get("plant_productivity"),
            plant_average,
            f"{len(plant_months)}-mo avg" if plant_months else "History unavailable",
            higher_is_better=True,
        ),
        "labour_percentage": build_kpi_comparison(
            production_mtd.get("summary", {}).get("labour_percentage_mtd"),
            labour_average,
            f"{len(labour_months)}-mo avg" if labour_months else "History unavailable",
            higher_is_better=False,
            comparison_available=current_invoice > 0,
        ),
        "debtor_days": build_kpi_comparison(
            accounts.get("average_debtor_days"),
            debtor_average,
            f"{len(debtor_values)}-day avg" if debtor_values else "Building history",
            higher_is_better=False,
            unit="days",
        ),
    }


def render_kpi_trend(comparison):
    comparison = comparison or {}
    average = comparison.get("average")
    label = str(comparison.get("period_label") or "History unavailable")
    unit = str(comparison.get("unit") or "%")
    value_suffix = "%" if unit == "%" else f" {unit}"
    delta_suffix = "pp" if unit == "%" else unit
    if average is None:
        return f'<span class="kpi-trend neutral"><span class="kpi-trend-copy"><b>{escape(label)}</b><small>No comparison yet</small></span></span>'
    if not comparison.get("comparison_available"):
        return f'<span class="kpi-trend neutral"><span class="kpi-trend-copy"><b>{escape(label)} {float(average):.1f}{escape(value_suffix)}</b><small>Awaiting invoiced revenue</small></span></span>'
    delta = float(comparison.get("current") or 0) - float(average)
    if abs(delta) < 0.05:
        arrow, direction, trend_class = "→", "in line", "neutral"
    else:
        arrow = "↑" if delta > 0 else "↓"
        direction = "above" if delta > 0 else "below"
        improved = (delta > 0) if comparison.get("higher_is_better") else (delta < 0)
        trend_class = "good" if improved else "bad"
    return (
        f'<span class="kpi-trend {trend_class}"><span class="kpi-trend-arrow">{arrow}</span>'
        f'<span class="kpi-trend-copy"><b>{escape(label)} {float(average):.1f}{escape(value_suffix)}</b>'
        f'<small>{abs(delta):.1f} {escape(delta_suffix)} {direction}</small></span></span>'
    )


def is_priority_one_customer(customer):
    value = str((customer or {}).get("priority") or "").strip()
    try:
        return float(value) == 1
    except ValueError:
        return value.casefold() in {"priority 1", "p1"}


def build_open_promises(crm_result):
    activities = crm_result.get("activities", []) if crm_result.get("status") == "ok" else []
    promises = []
    for activity in activities:
        if str(activity.get("crm_type") or "").strip().casefold() != "promise of order":
            continue
        if bool(activity.get("crm_is_complete")):
            continue
        created_at = parse_crm_datetime(activity.get("date_created"))
        age_days = max((datetime.now() - created_at).days, 0) if created_at else None
        customer = str(
            activity.get("customer_company")
            or activity.get("customer_label")
            or activity.get("recipient_company")
            or activity.get("sender_company")
            or "Customer not identified"
        ).strip()
        promises.append({
            "customer": customer,
            "customer_primary_key": str(activity.get("customer_primary_key") or "").strip(),
            "promise": str(activity.get("subject") or activity.get("body") or "Promise details not recorded").strip(),
            "created_at": str(activity.get("date_created") or "").strip(),
            "created_label": format_optional_datetime(activity.get("date_created")),
            "age_days": age_days,
            "owner": str(activity.get("sender_email") or "Owner not recorded").strip(),
            "completion": str(activity.get("crm_complete") or "").strip(),
        })
    promises.sort(key=lambda item: parse_crm_datetime(item.get("created_at")) or datetime.min, reverse=True)
    return promises


def get_priority_one_customers(master_data_result=None):
    master_data_result = master_data_result or fetch_filemaker_master_data()
    if master_data_result.get("status") != "ok":
        return [], master_data_result
    customers = [
        customer for customer in master_data_result.get("companies", [])
        if str(customer.get("type") or "").strip().casefold() == "customer"
        and is_priority_one_customer(customer)
    ]
    customers.sort(key=lambda item: str(item.get("company") or "").casefold())
    return customers, master_data_result


def build_weekly_kpi_dashboard_payload(crm_result=None, production_result=None, calendar_result=None, finance_result=None, master_data_result=None):
    if crm_result is None:
        crm_result = fetch_promise_of_order_activities()
        if crm_result.get("status") != "ok":
            crm_result = fetch_crm_activities()
    promises = build_open_promises(crm_result)
    customer_count = len({item["customer"].casefold() for item in promises if item["customer"]})
    aged_promises = [item for item in promises if item.get("age_days") is not None]
    production_result = production_result or fetch_production_analysis_data()
    production_mtd = build_current_month_production_payload(production_result=production_result)
    if calendar_result is None:
        calendar_start = datetime.now(UK_TIMEZONE).replace(hour=0, minute=0, second=0, microsecond=0)
        calendar_result = fetch_calendar_events(calendar_start, calendar_start + timedelta(days=14))
    planned_visits = calendar_result.get("events", []) if calendar_result.get("status") == "ok" else []
    finance_result = finance_result or fetch_aged_debt_summary()
    daily_invoice_target = get_daily_invoice_target()
    elapsed_invoice_target = calculate_elapsed_invoice_target(production_mtd.get("period_end"), daily_invoice_target)
    invoiced_revenue_mtd = production_mtd.get("summary", {}).get("invoiced_revenue_mtd") or 0.0
    priority_customers, priority_result = get_priority_one_customers(master_data_result)
    account_payload = {
        **finance_result,
        "invoiced_revenue_mtd": invoiced_revenue_mtd,
        "daily_invoice_target": daily_invoice_target,
        "elapsed_invoice_target": elapsed_invoice_target,
        "invoice_target_pct": (invoiced_revenue_mtd / elapsed_invoice_target * 100) if elapsed_invoice_target else None,
    }

    return {
        "status": crm_result.get("status", "error"),
        "source": crm_result.get("source", ""),
        "synced_at": crm_result.get("synced_at") or crm_result.get("cache_updated_at") or "",
        "open_promises": promises,
        "production_mtd": production_mtd,
        "planned_visits": planned_visits,
        "calendar_status": calendar_result.get("status", "error"),
        "calendar_error": calendar_result.get("error_message", ""),
        "calendar_synced_at": calendar_result.get("synced_at", ""),
        "accounts": account_payload,
        "comparisons": build_kpi_historical_comparisons(production_result, production_mtd, account_payload),
        "priority_customers": priority_customers,
        "priority_status": priority_result.get("status", "error"),
        "summary": {
            "open_count": len(promises),
            "customer_count": customer_count,
            "new_last_7_days": sum(1 for item in promises if item.get("age_days") is not None and item["age_days"] <= 7),
            "oldest_days": max((item["age_days"] for item in aged_promises), default=None),
        },
    }


def render_kpi_planned_visits(events, calendar_status="ok", calendar_error=""):
    if calendar_status != "ok":
        return f"<p class='status error'>{escape(calendar_error or 'Shared calendar is currently unavailable.')}</p>"
    if not events:
        return "<div class='kpi-visits-empty'><strong>No planned visits</strong><span>Nothing is scheduled in the next two weeks.</span></div>"
    cards = []
    for event in events[:12]:
        start = calendar_event_datetime(event, "start")
        date_label = start.strftime("%a %d %b") if start else "Date unavailable"
        location = str(event.get("location") or "").strip()
        cards.append(f'''<a class="kpi-visit-card" href="/calendar-view?month={(start or datetime.now(UK_TIMEZONE)).strftime('%Y-%m')}&edit={quote(str(event.get('id') or ''))}">
            <span class="kpi-visit-date">{escape(date_label)}</span>
            <div><strong>{escape(str(event.get('subject') or 'Untitled event'))}</strong><small>{escape(format_calendar_event_time(event))}{f' · {escape(location)}' if location else ''}</small></div>
        </a>''')
    more = f"<p class='small muted'>Showing 12 of {len(events)} events. Open the calendar to see all.</p>" if len(events) > 12 else ""
    return f"<div class='kpi-visits-list'>{''.join(cards)}</div>{more}"


def render_open_promises_table(promises):
    if not promises:
        return "<p class='empty-action'>No open promises of order were found in the current CRM data.</p>"

    rows = []
    for item in promises:
        customer = str(item.get("customer") or "Customer not identified")
        customer_href = f"/customer-view?customer={quote(customer)}"
        rows.append(f"""
            <tr>
                <td data-label="Customer"><a href="{escape(customer_href)}"><strong>{escape(customer)}</strong></a></td>
                <td data-label="Promise">{escape(str(item.get("promise") or ""))}</td>
            </tr>
        """)

    return f"""
        <div class="table-wrap kpi-promises-table-wrap">
            <table class="contacts-table kpi-promises-table">
                <colgroup><col class="kpi-customer-column"><col class="kpi-promise-column"></colgroup>
                <thead><tr><th>Customer</th><th>Promise</th></tr></thead>
                <tbody>{''.join(rows)}</tbody>
            </table>
        </div>
    """


def render_priority_customer_comms(activities):
    if not activities:
        return "<span class='muted'>No linked CRM communications</span>"
    items = []
    for activity in activities[:2]:
        date_label = format_optional_datetime(activity.get("date_created"))
        direction = str(activity.get("direction") or "Communication").strip().title()
        detail = clean_activity_content(activity.get("subject")) or clean_activity_content(activity.get("body"))
        items.append(
            f"<li><strong>{escape(date_label)}</strong> · {escape(direction)} · {escape(truncate_text(detail, 150) or 'No summary recorded')}</li>"
        )
    return f"<ul class='kpi-brief-comms'>{''.join(items)}</ul>"


