    position: str = Form(""),
    email: str = Form(""),
    phone: str = Form(""),
    cell: str = Form(""),
    state: str = Form(""),
    return_company: str = Form(""),
    return_name: str = Form(""),
    return_email: str = Form(""),
    return_position: str = Form(""),
    return_sort: str = Form("company"),
    return_direction: str = Form("asc"),
