@app.get("/contacts-view", response_class=HTMLResponse)
def get_contacts_view(
    company: str = "",
    name: str = "",
    email: str = "",
    position: str = "",
    sort: str = "company",
    direction: str = "asc",
    page: int = 1,
    message: str = "",
    error: str = "",
):
    master_data_result = fetch_filemaker_master_data()

    if master_data_result.get("status") != "ok":
        return render_page(
            title="Contacts",
            body=(
                f"<p class='status error'>Could not load contact master data from "
                f"FileMaker: {escape(master_data_result.get('status', 'unknown_error'))}</p>"
            )
        )

    contact_rows = [
        row for row in build_contact_master_rows(master_data_result)
        if not is_unknown_contact_row(row)
    ]
    filtered_contact_rows = filter_contact_master_rows(
        contact_rows,
        company=company,
        name=name,
        email=email,
        position=position,
    )
    sorted_contact_rows = sort_contact_master_rows(
        filtered_contact_rows,
        sort_key=sort,
        direction=direction,
    )
    page_size = 50
    total_filtered = len(sorted_contact_rows)
    total_pages = max(1, (total_filtered + page_size - 1) // page_size)
    page = max(1, min(int(page or 1), total_pages))
    start_index = (page - 1) * page_size
    paged_contact_rows = sorted_contact_rows[start_index:start_index + page_size]
    company_count = len({
        row["customer_ref"]
        for row in contact_rows
        if row.get("customer_ref")
    })

    strategic_lookup = build_saved_strategic_contact_sets(load_strategic_contacts())
    current_user = get_current_session_user()
    can_manage = can_manage_strategic_contacts(current_user)
    status_markup = ""
    if message:
        status_markup = f"<p class='status ok'>{escape(message)}</p>"
    elif error:
        status_markup = f"<p class='status error'>{escape(error)}</p>"
    rows = "".join(
        render_contact_master_row(
            contact,
            existing_lookup=strategic_lookup,
            current_filters={
                "company": company,
                "name": name,
                "email": email,
                "position": position,
                "sort": sort,
                "direction": direction,
                "page": page,
            },
            can_manage=can_manage,
        )
        for contact in paged_contact_rows
    )

    if not rows:
        rows = (
            "<tr>"
            f"<td colspan='6' class='empty'>No contacts match the current filters.</td>"
            "</tr>"
        )

    body = f"""
        {status_markup}
        {render_data_availability_banner(master_data_result)}

        <div class="summary customer-summary">
            <div>
                <span class="label">Source</span>
                <strong>FileMaker master data</strong>
            </div>
            <div>
                <span class="label">Contacts</span>
                <strong>{len(contact_rows)}</strong>
            </div>
            <div>
                <span class="label">Showing</span>
                <strong>{len(paged_contact_rows)}</strong>
            </div>
            <div>
                <span class="label">Companies</span>
                <strong>{company_count}</strong>
            </div>
        </div>

        <div class="contacts-filter-panel">
            {render_contacts_filter_form(company, name, email, position, sort, direction)}
        </div>

        <div class="table-wrap tall-table">
        <table class="contacts-table">
            <thead>
                <tr>
                    <th>Company</th>
                    <th>Contact</th>
                    <th>Email</th>
                    <th>Status</th>
                    <th>Position</th>
                    <th>Strategic</th>
                </tr>
            </thead>
            <tbody>{rows}</tbody>
        </table>
        </div>
        {render_contacts_pagination(company, name, email, position, sort, direction, page, total_pages, total_filtered, start_index, len(paged_contact_rows))}
        <script>
            (function () {{
                const windowScrollKey = "contacts-view-return-scroll-v1";
                const tableScrollKey = "contacts-view-return-table-scroll-v1";
                const tableWrap = document.querySelector(".table-wrap.tall-table");
                const rowAnchor = window.location.hash ? window.location.hash.slice(1) : "";

                try {{
                    const savedWindowScroll = window.sessionStorage.getItem(windowScrollKey);
                    const savedTableScroll = window.sessionStorage.getItem(tableScrollKey);
                    window.sessionStorage.removeItem(windowScrollKey);
                    window.sessionStorage.removeItem(tableScrollKey);

                    window.requestAnimationFrame(() => {{
                        if (rowAnchor) {{
                            const row = document.getElementById(rowAnchor);
                            if (row) {{
                                row.scrollIntoView({{ block: "center", behavior: "auto" }});
                                return;
                            }}
                        }}

                        if (tableWrap && savedTableScroll) {{
                            const top = Number(savedTableScroll);
                            if (Number.isFinite(top) && top >= 0) {{
                                tableWrap.scrollTop = top;
                                return;
                            }}
                        }}

                        if (savedWindowScroll) {{
                            const y = Number(savedWindowScroll);
                            if (Number.isFinite(y) && y >= 0) {{
                                window.scrollTo({{ top: y, behavior: "auto" }});
                            }}
                        }}
                    }});
                }} catch (error) {{
                    // ignore storage issues
                }}

                document.querySelectorAll('form[action="/strategic-contacts/import-contact"]').forEach((form) => {{
                    form.addEventListener("submit", () => {{
                        try {{
                            window.sessionStorage.setItem(windowScrollKey, String(window.scrollY || window.pageYOffset || 0));
                            if (tableWrap) {{
                                window.sessionStorage.setItem(tableScrollKey, String(tableWrap.scrollTop || 0));
                            }}
                        }} catch (error) {{
                            // ignore storage issues
                        }}
                    }});
                }});
            }})();
        </script>
    """

    return render_page(title="Contacts", body=body)


