def is_contact_in_strategic_contacts(contact, existing_lookup):
    company_name = str(contact.get("company") or "").strip()
    contact_name = str(contact.get("name") or "").strip()
    position = str(contact.get("position") or "").strip()
    email = str(contact.get("email") or "").strip().lower()
    phone = str(contact.get("phone") or "").strip()
    cell = str(contact.get("cell") or "").strip()

    return (
        is_saved_strategic_contact(email, phone, contact_name, company_name, position, existing_lookup)
        or is_saved_strategic_contact(email, cell, contact_name, company_name, position, existing_lookup)
    )


def render_contact_master_row(contact, existing_lookup=None, current_filters=None, can_manage=False):
    company_name = str(contact.get("company") or "")
    customer_ref = str(contact.get("customer_ref") or "")
    row_anchor_parts = [
        customer_ref or company_name,
        str(contact.get("name") or "").strip(),
        str(contact.get("email") or "").strip(),
    ]
    row_anchor = "contact-row-" + re.sub(
        r"[^a-z0-9]+",
        "-",
        normalize_apollo_location_value("|".join(bit for bit in row_anchor_parts if bit)) or "contact",
    ).strip("-")
    customers_href = f"/customers-view?customer={quote(company_name)}" if company_name else "/customers-view"
    company_markup = (
        f'<a href="{customers_href}"><strong>{escape(company_name)}</strong></a>'
        if company_name
        else "<span class='muted'>Unknown company</span>"
    )
    contact_name = str(contact.get("name") or "").strip() or "Unknown contact"
    state = str(contact.get("state") or "").strip() or "n/a"
    position = str(contact.get("position") or "").strip() or "—"
    email = str(contact.get("email") or "").strip() or "—"
    phone = str(contact.get("phone") or "").strip() or "—"
    cell = str(contact.get("cell") or "").strip() or "—"
    active_label = str(contact.get("active") or "").strip() or "Unknown"
    active_markup = (
        "<span class='contact-status contact-status-active'>Active</span>"
        if active_label.lower() == "active"
        else f"<span class='contact-status contact-status-inactive'>{escape(active_label.title())}</span>"
    )
    current_filters = current_filters or {}
    already_saved = bool(existing_lookup and is_contact_in_strategic_contacts(contact, existing_lookup))
    saved_contact_id = (
        get_saved_strategic_contact_id(email, phone, contact_name, company_name, position, existing_lookup)
        if already_saved and existing_lookup
        else ""
    )
    return_url = (
        "/contacts-view"
        f"?company={quote(str(current_filters.get('company') or ''))}"
        f"&name={quote(str(current_filters.get('name') or ''))}"
        f"&email={quote(str(current_filters.get('email') or ''))}"
        f"&position={quote(str(current_filters.get('position') or ''))}"
        f"&sort={quote(str(current_filters.get('sort') or 'company'))}"
        f"&direction={quote(str(current_filters.get('direction') or 'asc'))}"
        f"&page={quote(str(current_filters.get('page') or '1'))}"
        f"#{quote(row_anchor)}"
    )
    strategic_action = ""
    if can_manage:
        if already_saved and saved_contact_id:
            strategic_action = f"""
                <form method="post" action="/strategic-contacts/delete" class="inline-form">
                    <input type="hidden" name="contact_id" value="{escape(saved_contact_id)}" />
                    <input type="hidden" name="return_to" value="{escape(return_url)}" />
                    <button class="contact-status contact-status-active contact-status-button" type="submit">Saved</button>
                </form>
            """
        elif already_saved:
            strategic_action = "<span class='contact-status contact-status-active'>Saved</span>"
        else:
            strategic_action = f"""
                <form method="post" action="/strategic-contacts/import-contact" class="inline-form">
                    <input type="hidden" name="company" value="{escape(company_name)}" />
                    <input type="hidden" name="customer_ref" value="{escape(customer_ref)}" />
                    <input type="hidden" name="name" value="{escape(contact_name)}" />
                    <input type="hidden" name="position" value="{escape(position if position != '—' else '')}" />
                    <input type="hidden" name="email" value="{escape('' if email == '—' else email)}" />
                    <input type="hidden" name="phone" value="{escape('' if phone == '—' else phone)}" />
                    <input type="hidden" name="cell" value="{escape('' if cell == '—' else cell)}" />
                    <input type="hidden" name="state" value="{escape(state if state != 'n/a' else '')}" />
                    <input type="hidden" name="return_company" value="{escape(str(current_filters.get('company') or ''))}" />
                    <input type="hidden" name="return_name" value="{escape(str(current_filters.get('name') or ''))}" />
                    <input type="hidden" name="return_email" value="{escape(str(current_filters.get('email') or ''))}" />
                    <input type="hidden" name="return_position" value="{escape(str(current_filters.get('position') or ''))}" />
                    <input type="hidden" name="return_sort" value="{escape(str(current_filters.get('sort') or 'company'))}" />
                    <input type="hidden" name="return_direction" value="{escape(str(current_filters.get('direction') or 'asc'))}" />
                    <input type="hidden" name="return_page" value="{escape(str(current_filters.get('page') or '1'))}" />
                    <input type="hidden" name="return_anchor" value="{escape(row_anchor)}" />
                    <button class="button secondary small-button" type="submit">Save to Strategic Contacts</button>
                </form>
            """

    return f"""
        <tr id="{escape(row_anchor)}">
            <td>{company_markup}</td>
            <td><strong>{escape(contact_name)}</strong></td>
            <td>{escape(email)}</td>
            <td>{active_markup}</td>
            <td>{escape(position)}</td>
            <td>{strategic_action}</td>
        </tr>
    """


def render_customer_crm_timeline(customer, activities, crm_limit, crm_page, crm_direction, crm_category, sort, direction):
    total_pages = max(1, (len(activities) + crm_limit - 1) // crm_limit)
    crm_page = max(1, min(crm_page, total_pages))
    start_index = (crm_page - 1) * crm_limit
    shown_activities = activities[start_index:start_index + crm_limit]
    shown_count = len(shown_activities)
    summary_html = render_customer_crm_timeline_summary(
        activities=activities,
        crm_direction=crm_direction,
        crm_category=crm_category,
        start_index=start_index,
        shown_count=shown_count,
    )
    rows = "".join(
        render_customer_crm_activity(activity)
        for activity in shown_activities
    )

    if not rows:
        rows = (
            "<tr>"
            "<td colspan='5' class='empty'>No CRM email history linked to this customer key yet.</td>"
            "</tr>"
        )

    pagination_html = render_customer_crm_pagination(
        customer=customer,
        crm_page=crm_page,
        total_pages=total_pages,
        crm_limit=crm_limit,
        crm_direction=crm_direction,
        crm_category=crm_category,
        sort=sort,
        direction=direction,
    )

    return f"""
        <section class="panel" id="crm-timeline">
            <h2>CRM Timeline</h2>
            {summary_html}
            {render_customer_crm_timeline_controls(customer, crm_direction, crm_category, crm_limit, sort, direction)}
            <div class="table-wrap tall-table crm-timeline-wrap">
            <table class="crm-timeline-table">
                <thead>
                    <tr>
                        <th>Date</th>
                        <th>Direction</th>
                        <th>Subject</th>
                        <th>From / To</th>
                        <th>Preview</th>
                    </tr>
                </thead>
                <tbody>{rows}</tbody>
            </table>
            </div>
            {pagination_html}
        </section>
    """


def render_customer_crm_timeline_summary(activities, crm_direction, crm_category, start_index, shown_count):
    parts = [
        (
            f"Showing {start_index + 1 if activities else 0} to "
            f"{start_index + shown_count} of {len(activities)} matched customer emails"
        )
    ]
    direction_value = str(crm_direction or "").strip().lower()

    if direction_value:
        parts.append(f"direction: {direction_value.title()}")
    else:
        direction_counts = Counter(
            str(activity.get("direction") or "").strip().lower()
            for activity in activities
            if str(activity.get("direction") or "").strip()
        )
        inbound_count = direction_counts.get("inbound", 0)
        outbound_count = direction_counts.get("outbound", 0)
        unknown_count = direction_counts.get("unknown", 0)
        parts.append(f"inbound: {inbound_count}")
        parts.append(f"outbound: {outbound_count}")

        if unknown_count:
            parts.append(f"unknown: {unknown_count}")

    category_value = str(crm_category or "").strip().lower()
    if category_value:
        parts.append(f"category: {category_value.replace('_', ' ').title()}")

    return (
        "<p class=\"filter-summary\">"
        + " | ".join(escape(part) for part in parts)
        + "</p>"
    )


