def build_home_action_plan(
    attention_customers,
    grouped_orders,
    crm_activity_map,
    dismissed_customers=None,
    group_filter="all",
    territory_filter="all",
    customers_by_key=None,
):
    due_today_customers = []
    dismissed_customers = dismissed_customers or []
    normalized_group_filter = normalize_action_plan_group_filter(group_filter)
    normalized_territory_filter = normalize_action_plan_territory_filter(territory_filter)
    customers_by_key = customers_by_key or {}

    for customer in attention_customers:
        customer_name = str(customer.get("customer", ""))
        customer_orders = grouped_orders.get(customer_name, [])
        customer_primary_key = get_customer_primary_key(customer_orders)
        customer_record = customers_by_key.get(customer_primary_key, {})
        customer_group = infer_customer_group_code(
            customer_name,
            customer_orders=customer_orders,
            customer_record=customer_record,
        )

        if normalized_group_filter != "all" and customer_group != normalized_group_filter:
            continue

        territory = get_customer_territory(customer_orders)
        if (
            normalized_territory_filter != "all"
            and normalize_customer_territory(territory) != normalized_territory_filter
        ):
            continue

        crm_activities = crm_activity_map.get(customer_primary_key, [])
        crm_activities = merge_recent_sent_emails_with_crm(customer_name, crm_activities)
        sales_activities = get_sales_outreach_activities(crm_activities)
        outbound_sales = [
            activity for activity in sales_activities
            if str(activity.get("direction") or "").strip().lower() == "outbound"
        ]
        contact_policy = build_action_plan_contact_policy(outbound_sales, customer_name=customer_name)
        enriched_customer = dict(customer)
        enriched_customer["territory"] = territory.title() if territory else "Unassigned"
        enriched_customer["last_order"] = (
            max(order.get("order_date", "") for order in customer_orders)
            if customer_orders else ""
        )

        if contact_policy.get("exclude_from_action_plan"):
            continue

        if has_recent_activity(enriched_customer.get("days_since_last_activity")):
            continue

        if float(enriched_customer.get("priority_score") or 0) >= 1.5:
            due_today_customers.append(enriched_customer)

    due_today_customers = sort_late_customers(
        due_today_customers,
        sort_key="priority_score",
        direction="desc",
    )[:10]
    dismissed_customers = [
        customer for customer in dismissed_customers
        if float(customer.get("priority_score") or 0) >= 1.5
    ]

    return {
        "due_today": due_today_customers,
        "dismissed": dismissed_customers,
    }


def get_customer_territory(customer_orders):
    territories = Counter(
        str(get_order_territory(order) or "").strip()
        for order in customer_orders
        if str(get_order_territory(order) or "").strip()
    )
    return territories.most_common(1)[0][0] if territories else ""


def normalize_customer_territory(value):
    territory = str(value or "").strip().lower()
    if re.search(r"\beast\b", territory):
        return "east"
    if re.search(r"\bwest\b", territory):
        return "west"
    return ""


def get_action_plan_dismissals_path():
    raw_path = os.getenv("ACTION_PLAN_DISMISSALS_PATH", "").strip()

    if raw_path:
        return Path(raw_path).expanduser()

    return DEFAULT_ACTION_PLAN_DISMISSALS_PATH


def read_action_plan_dismissals():
    dismissals_path = get_action_plan_dismissals_path()

    try:
        if not dismissals_path.exists():
            return {}

        payload = json.loads(dismissals_path.read_text(encoding="utf-8"))
    except (OSError, ValueError, TypeError):
        return {}

    if not isinstance(payload, dict):
        return {}

    normalized = {}

    for customer_name, dismissal in payload.items():
        if not isinstance(dismissal, dict):
            continue

        normalized[str(customer_name)] = {
            "last_order": str(dismissal.get("last_order") or "").strip(),
            "dismissed_at": str(dismissal.get("dismissed_at") or "").strip(),
            "reason": str(dismissal.get("reason") or "").strip(),
        }

    return normalized


def write_action_plan_dismissals(dismissals):
    dismissals_path = get_action_plan_dismissals_path()
    dismissals_path.parent.mkdir(parents=True, exist_ok=True)
    dismissals_path.write_text(json.dumps(dismissals, indent=2), encoding="utf-8")


def get_action_plan_dismissal(customer_name, last_order, dismissals=None):
    dismissals = dismissals or read_action_plan_dismissals()
    dismissal = dismissals.get(str(customer_name))

    if not dismissal:
        return None

    if str(dismissal.get("last_order") or "").strip() != str(last_order or "").strip():
        return None

    return dismissal

def is_action_plan_dismissed(customer_name, last_order, dismissals=None):
    return bool(get_action_plan_dismissal(customer_name, last_order, dismissals=dismissals))


def dismiss_action_plan_customer(customer_name, last_order, reason=""):
    dismissals = read_action_plan_dismissals()
    dismissals[str(customer_name)] = {
        "last_order": str(last_order or "").strip(),
        "dismissed_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "reason": str(reason or "").strip(),
    }
    write_action_plan_dismissals(dismissals)
    clear_attention_response_cache()
    clear_home_queue_summaries_cache()
    clear_customer_summaries_cache()


def restore_action_plan_customer(customer_name):
    dismissals = read_action_plan_dismissals()

    if str(customer_name) in dismissals:
        dismissals.pop(str(customer_name), None)
        write_action_plan_dismissals(dismissals)
        clear_attention_response_cache()
        clear_home_queue_summaries_cache()
        clear_customer_summaries_cache()


def get_order_territory(order):
    extra = order.get("extra", {})
    return extra.get("Companies 4::Territory") or extra.get("ai_Territory") or ""


def get_order_state(order):
    extra = order.get("extra", {})
    return extra.get("Companies 4::State") or extra.get("ai_State") or ""


def get_order_price_list(order):
    extra = order.get("extra", {})
    return extra.get("Companies 4::Price List") or extra.get("ai_PriceList") or ""


def get_order_primary_key(order):
    extra = order.get("extra", {})
    return extra.get("Companies 4::PrimaryKey") or extra.get("Customer Ref") or ""


def get_crm_days_since_latest_activity(latest_crm_activity):
    if not latest_crm_activity:
        return None

    activity_date = parse_crm_datetime(latest_crm_activity.get("date_created", ""))

    if not activity_date:
        return None

    return (get_analysis_today().date() - activity_date.date()).days


def has_expired_relative_timing(text, age_days):
    """Return true when relative scheduling language is no longer current."""
    if not isinstance(age_days, (int, float)) or age_days < 0:
        return False

    lowered = str(text or "").lower()
    thresholds = {
        "tomorrow": 2,
        "later this week": 7,
        "this week": 7,
        "next week": 14,
        "later this month": 31,
        "this month": 31,
        "next month": 45,
    }
    return any(phrase in lowered and age_days > max_age for phrase, max_age in thresholds.items())


def has_likely_order_intent(text):
    """Identify CRM notes describing mats expected for a future repair order."""
    lowered = str(text or "").lower()
    phrases = [
        "mats ready",
        "ready for repair",
        "ready to repair",
        "next order",
        "send an order",
        "place an order",
        "repair order",
        "pickup arranged",
        "pick up arranged",
    ]
    return any(phrase in lowered for phrase in phrases)


def get_sales_outreach_activities(activities):
    return [
        activity
        for activity in activities
        if get_activity_category(activity) != "customer_services"
    ]


def sort_sales_activities_by_date(activities):
    return sorted(
        activities,
        key=lambda activity: parse_crm_datetime(activity.get("date_created", "")) or datetime.min,
        reverse=True,
    )


def build_action_plan_contact_policy(outbound_sales, customer_name=""):
    sorted_outbound = sort_sales_activities_by_date(outbound_sales)
    latest_contact_days = None
    latest_email_days = None
    latest_call_days = None
    latest_direct_touch_days = None
    email_first_customer = is_email_first_corporate_customer(customer_name)
    ignore_recent_contact_hold = should_ignore_action_plan_recent_contact_hold(customer_name)

    for activity in sorted_outbound:
        activity_days = get_crm_days_since_latest_activity(activity)
        if activity_days is None or activity_days < 0:
            continue

        if latest_contact_days is None:
            latest_contact_days = activity_days

        normalized_type = normalize_sales_activity_type(activity.get("crm_type"))
        if normalized_type == "email" and latest_email_days is None:
            latest_email_days = activity_days
        if normalized_type == "call" and latest_call_days is None:
            latest_call_days = activity_days
        if normalized_type in {"call", "text"} and latest_direct_touch_days is None:
            latest_direct_touch_days = activity_days

    has_email = latest_email_days is not None
    has_call = latest_call_days is not None
    has_direct_touch = latest_direct_touch_days is not None
    recent_contact_hold = latest_contact_days is not None and latest_contact_days <= 7
    email_follow_up_window = latest_email_days is not None and 7 < latest_email_days < 30
    direct_touch_cooloff_hold = (
        has_email
        and has_direct_touch
        and latest_direct_touch_days is not None
        and 0 <= latest_direct_touch_days < 30
    )

    exclude_from_action_plan = (
        False
        if ignore_recent_contact_hold
        else (recent_contact_hold or direct_touch_cooloff_hold)
    )
    hold_reason = ""
    mode_override = ""
    why_override = ""

    if ignore_recent_contact_hold:
        mode_override = "Email"
        why_override = "Testing override enabled for this customer • recent contact hold ignored"
    elif direct_touch_cooloff_hold:
        hold_reason = "Recent email and direct follow-up already logged"
        mode_override = "Hold"
        why_override = "Email and call/text already logged • wait until 30 days since the latest direct follow-up"
    elif recent_contact_hold:
        hold_reason = "Recent contact already logged in the last 7 days"
        mode_override = "Hold"
        why_override = f"Recent contact logged {latest_contact_days} days ago • avoid duplicate follow-up"
    elif email_follow_up_window:
        if email_first_customer:
            mode_override = "Email"
            why_override = f"Recent email sent {latest_email_days} days ago • email remains the preferred channel for this account"
        else:
            mode_override = "Call"
            why_override = f"Recent email sent {latest_email_days} days ago • follow up with a phone call"

    return {
        "exclude_from_action_plan": exclude_from_action_plan,
        "hold_reason": hold_reason,
        "mode_override": mode_override,
        "why_override": why_override,
        "latest_contact_days": latest_contact_days,
        "latest_email_days": latest_email_days,
        "latest_call_days": latest_call_days,
        "latest_direct_touch_days": latest_direct_touch_days,
        "has_email": has_email,
        "has_call": has_call,
        "has_direct_touch": has_direct_touch,
        "email_first_customer": email_first_customer,
    }


def get_activity_category(activity):
    category_value = str(activity.get("activity_category") or "").strip().lower()

    if category_value:
        return category_value

    sender_email = str(activity.get("sender_email") or "").strip().lower()
    recipient_emails = extract_emails(str(activity.get("to") or ""))
    sender_company = str(activity.get("sender_company") or "").strip()
    subject = str(activity.get("subject") or "").strip()
    body = str(activity.get("body") or "").strip()

    if is_customer_service_activity(
        sender_email=sender_email,
        recipient_emails=recipient_emails,
        sender_company=sender_company,
        subject=subject,
        body=body,
    ):
        return "customer_services"

    return "sales_outreach"


